<?php session_start(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['username']??'')==='admin'&&($_POST['password']??'')==='admin123'){session_regenerate_id(true);$_SESSION['logged_in']=true;header('Location: index.php');exit;} $error='Invalid username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employee Login</title><link rel="stylesheet" href="assets/style.css"></head><body><main><h1>Employee Portal</h1><p>PHP session login · Lab 09</p><?php if($error)echo '<p class="error">'.htmlspecialchars($error).'</p>'; ?><form method="post"><label>Username<input name="username" required></label><label>Password<input name="password" type="password" required></label><button>Login</button></form><p class="note">Demo login: admin / admin123</p></main></body></html>